Use a newly generated accessToken for initialization and prepare an expiration handler. Standalone example of WebSDK initialization The following is a fully working example — change the $ACCESS_TOKEN variable with the appropriate value, save it to an HTML file, and open it in your browser. <html> <head> <title>WebSDK CDN Example</title> </head> <body> <script src="https://static.sumsub.com/idensic/static/sns-websdk-builder.js"></script> <div id="sumsub-websdk-container"></div> </body> </html> <script> function launchWebSdk(accessToken, applicantEmail, applicantPhone) { let snsWebSdkInstance = snsWebSdk .init(accessToken, () => this.getNewAccessToken()) .withConf({ lang: "en", email: applicantEmail, phone: applicantPhone, }) .withOptions({ addViewportTag: false, adaptIframeHeight: true }) .on("idCheck.onStepCompleted", (payload) => { console.log("onStepCompleted", payload); }) .on("idCheck.onError", (error) => { console.log("onError", error); }) .onMessage((type, payload) => { console.log("onMessage", type, payload); }) .build(); snsWebSdkInstance.launch("#sumsub-websdk-container"); } // Requests a new access token from the backend side. function getNewAccessToken() { return Promise.resolve($NEW_ACCESS_TOKEN); } launchWebSdk($ACCESS_TOKEN); </script> <html> <head> <title>WebSDK CDN Example</title> </head> <body> <script src="https://static.sumsub.com/idensic/static/sns-websdk-builder.js"></script> <div id="sumsub-websdk-container"></div> </body> </html> <script> function launchWebSdk(accessToken, applicantEmail, applicantPhone) { let snsWebSdkInstance = snsWebSdk .init(accessToken, () => this.getNewAccessToken()) .withConf({ lang: "en", email: applicantEmail, phone: applicantPhone, i18n: { document: { subTitles: { IDENTITY: "Upload a document that proves your identity" } } }, onMessage: (type, payload) => { console.log("WebSDK onMessage", type, payload); }, uiConf: { customCssStr: ":root {
